# Variables to store the processed data
data_summary = []

# Function to process lines 1-22 and extract relevant information
def process_file(file_path):
    extracted_data = {}
    with open(file_path, 'r') as file:
        for i, line in enumerate(file):
            if i == 22:  # Stop after line 22
                break
            line = line.strip()
            if line.startswith("Alpha:"):
                extracted_data["Alpha"] = float(line.split(":")[1].strip())
            elif line.startswith("Beta:"):
                extracted_data["Beta"] = float(line.split(":")[1].strip())
            elif line.startswith("Chi:"):
                extracted_data["Chi"] = float(line.split(":")[1].strip())
            elif line.startswith("Delta:"):
                extracted_data["Delta"] = float(line.split(":")[1].strip())
            elif line.startswith("Epsilon:"):
                extracted_data["Epsilon"] = float(line.split(":")[1].strip())
            elif line.startswith("MaxIter:"):
                extracted_data["MaxIter"] = int(line.split(":")[1].strip())
            elif line.startswith("Seed:"):
                extracted_data["Seed"] = int(line.split(":")[1].strip())
